@Test
void testObjectsWithinFunction() {
    Map<String, Object> map = new HashMap();
    map.put("a", 1);
    map.put("b", 2);
    je.put("o", map);
    JsValue jv = je.eval("(function(){ return Object.entries(o) })()");
    List result = jv.getAsList();
    Match.that(result).isEqualTo("[[a, 1],[b, 2]]");
}

